//! Copies the channels table generated by Nix into `OUT_DIR`.
//!
//! The categories are declared in `assets/channels.nix` and generated by
//! `nix/scripts/gen-broadcast.py`, which is also what refuses an iptv-org
//! category that does not exist. This build script does NOT generate them —
//! generating here would reimplement Nix logic (invariant 5) and would lose
//! the one refusal that matters. Same shape as `ronoctua-world/build.rs`.

use std::{env, fs, path::PathBuf};

fn main() {
    println!("cargo:rerun-if-env-changed=RONOCTUA_BROADCAST_RS");

    let generated = env::var("RONOCTUA_BROADCAST_RS").unwrap_or_else(|_| {
        panic!(
            "RONOCTUA_BROADCAST_RS is not set.\n\
             \n\
             The player's channels by theme are generated by Nix out of\n\
             assets/channels.nix. Enter the environment with `direnv allow` (or\n\
             `nix develop`), which sets the variable, or build through the flake\n\
             with `nix build`."
        )
    });

    println!("cargo:rerun-if-changed={generated}");

    let destination = PathBuf::from(env::var("OUT_DIR").expect("OUT_DIR")).join("broadcast.rs");
    // DELETE FIRST — the store file is read-only. See `ronoctua-tokens/build.rs`.
    let _ = fs::remove_file(&destination);
    fs::copy(&generated, &destination)
        .unwrap_or_else(|e| panic!("could not copy {generated} -> {destination:?}: {e}"));
}
